output_grid = parse_grid_23(output_text)

# For each non-background cell, check what becomes of it after "expansion"
# Try: if any neighbor (including diagonals) is 3, become 3
def expand_3s(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(1, h-1):
        for c in range(1, w-1):
            if grid[r][c] != 1:  # It's background
                # Check all 8 neighbors
                has_3 = False
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
